if (!msg.req || !msg.req.files || msg.req.files.length === 0) {
    return null;
}

let fileBuffer = msg.req.files[0].buffer;
let filename = msg.req.files[0].originalname;

try {
    let zip = new AdmZip(fileBuffer);
    let entries = zip.getEntries();
    let mainXmlStr = '';
    let langXmlStr = '';
    let fileMap = {};

    for (let entry of entries) {
        let entryName = entry.entryName.replace(/^.*[\\\/]/, ''); // Mappák levágása
        let lowerName = entryName.toLowerCase();

        // 1. XML fájlok felosztása (Fő leíró és szótárak)
        if (lowerName.endsWith('.xml')) {
            let content = zip.readAsText(entry);
            if (content.includes('<DeviceIdentity') || content.includes('<ProfileBody') || content.includes('<ISO15745')) {
                mainXmlStr = content;
            } else if (content.includes('<ExternalTextCollection') || content.includes('<PrimaryLanguage') || lowerName.includes('lang') || lowerName.includes('-en.')) {
                langXmlStr = content;
            }
        } 
        // 2. Képek beolvasása memóriába
        else if (lowerName.endsWith('.png') || lowerName.endsWith('.jpg') || lowerName.endsWith('.jpeg')) {
            let imgData = entry.getData();
            let mime = lowerName.endsWith('.png') ? 'image/png' : 'image/jpeg';
            fileMap[lowerName] = 'data:' + mime + ';base64,' + imgData.toString('base64');
        }
    }

    if (!mainXmlStr && langXmlStr) {
        mainXmlStr = langXmlStr;
    }

    if (!mainXmlStr) {
        node.status({ fill: 'red', shape: 'dot', text: 'Nincs érvényes XML' });
        return null;
    }

    // 3. FOTÓ KIVÁLASZTÁSA PONTOS SZABÁLYOK ALAPJÁN
    let selectedImage = null;
    let allPicKeys = Object.keys(fileMap);

    // 1. Szint: Kizárólag a tiszta termékfotó (-pic.png / -pic.jpg), de NEM -con-pic!
    let realPic = allPicKeys.find(k => {
        let isPic = (k.endsWith('-pic.png') || k.endsWith('-pic.jpg') || k.endsWith('-pic.jpeg') || k.includes('device-pic'));
        let isCon = k.includes('-con-') || k.includes('-con.') || k.includes('connect');
        return isPic && !isCon;
    });

    // 2. Szint: Termékikon (-icon.png), ha nincs -pic
    let iconPic = allPicKeys.find(k => {
        return (k.endsWith('-icon.png') || k.endsWith('-icon.jpg')) && !k.includes('-con-');
    });

    if (realPic) {
        selectedImage = fileMap[realPic];
    } else if (iconPic) {
        selectedImage = fileMap[iconPic];
    } else {
        // 3. Szint: Bármilyen kép, ami NEM bekötés és NEM logó
        let neutralPic = allPicKeys.find(k => {
            let isCon = k.includes('con') || k.includes('wire') || k.includes('pin') || k.includes('sch');
            let isLogo = k.includes('logo') || k.includes('vendor');
            return !isCon && !isLogo;
        });
        if (neutralPic) {
            selectedImage = fileMap[neutralPic];
        }
    }

    node.status({ fill: 'green', shape: 'dot', text: 'XML kinyerve: ' + filename });
    return {
        payload: mainXmlStr,
        langXml: langXmlStr,
        imageBase64: selectedImage,
        filename: filename,
        topic: 'iodd_xml'
    };
} catch (err) {
    node.status({ fill: 'red', shape: 'ring', text: 'ZIP hiba: ' + err.message });
    return null;
}

let rawPayload = msg.payload;

function findNodes(obj, targetKey, results = []) {
    if (!obj || typeof obj !== 'object') return results;
    for (let k in obj) {
        let cleanKey = k.replace(/^[a-zA-Z0-9_-]+:/, '');
        if (cleanKey.toLowerCase() === targetKey.toLowerCase()) {
            let val = obj[k];
            if (Array.isArray(val)) results.push(...val);
            else results.push(val);
        }
        if (typeof obj[k] === 'object') {
            findNodes(obj[k], targetKey, results);
        }
    }
    return results;
}

function findFirst(obj, targetKey) {
    let list = findNodes(obj, targetKey);
    return list.length > 0 ? list[0] : null;
}

function getAttr(node, attrName) {
    if (!node) return null;
    if (node.$) {
        for (let k in node.$) {
            if (k.toLowerCase() === attrName.toLowerCase()) return node.$[k];
        }
    }
    for (let k in node) {
        if (k.toLowerCase() === attrName.toLowerCase() && typeof node[k] !== 'object') return node[k];
    }
    return null;
}

// 1. Szótár felépítése
let textMap = {};
let allTexts = findNodes(rawPayload, 'Text');
allTexts.forEach(t => {
    let id = getAttr(t, 'id');
    let val = getAttr(t, 'value') || (typeof t._ === 'string' ? t._ : null) || id;
    if (id && val) textMap[id] = val;
});

function resolveText(idRef, fallback) {
    if (!idRef) return fallback || '';
    return textMap[idRef] || idRef;
}

// 2. Eszközazonosítók
let devIdentity = findFirst(rawPayload, 'DeviceIdentity');
let vendorId = getAttr(devIdentity, 'vendorId') || getAttr(devIdentity, 'vendorID') || 'N/A';
let deviceId = getAttr(devIdentity, 'deviceId') || getAttr(devIdentity, 'deviceID') || 'N/A';
let vendorName = getAttr(devIdentity, 'vendorName') || 'N/A';

let devVariant = findFirst(rawPayload, 'DeviceVariant');
let variantNameNode = devVariant ? findFirst(devVariant, 'Name') : null;
let devNameNode = findFirst(devIdentity, 'DeviceName');

let rawNameId = getAttr(variantNameNode, 'textId') || getAttr(devNameNode, 'textId') || (devVariant ? getAttr(devVariant, 'productId') : null);
let productName = resolveText(rawNameId, (devVariant ? getAttr(devVariant, 'productId') : null) || (vendorName !== 'N/A' ? vendorName + ' Eszköz' : 'IO-Link Eszköz'));

// 3. Globális Datatype tábla
let customTypes = {};
let allDatatypes = findNodes(rawPayload, 'Datatype');
allDatatypes.forEach(dt => {
    let dtId = getAttr(dt, 'id');
    if (dtId) customTypes[dtId] = dt;
});

let pdInElements = [];
let pdOutElements = [];
let paramElements = [];

// Rekord elemek feldolgozója
function parseRecordItems(items, parentId, groupName, access, targetList, isPd = false) {
    items.forEach(item => {
        let subindex = getAttr(item, 'subindex') || '1';
        let bitOffset = getAttr(item, 'bitOffset') || '0';
        let bitLength = getAttr(item, 'bitLength') || '8';
        let itemNameNode = findFirst(item, 'Name');
        let itemRawName = getAttr(itemNameNode, 'textId');
        let itemLabel = itemRawName ? resolveText(itemRawName, groupName) : (groupName + ' [Sub ' + subindex + ']');

        let sdt = findFirst(item, 'SimpleDatatype') || item;
        let sdtType = getAttr(sdt, 'xsi:type') || getAttr(sdt, 'datatype') || '';

        let singleValues = findNodes(sdt, 'SingleValue');
        if (singleValues.length > 0) {
            let options = singleValues.map(sv => {
                let svVal = getAttr(sv, 'value');
                let svNameNode = findFirst(sv, 'Name');
                let svTextId = getAttr(svNameNode, 'textId');
                return {
                    name: resolveText(svTextId, svVal),
                    value: isNaN(Number(svVal)) ? svVal : Number(svVal)
                };
            });

            targetList.push({
                type: 'dropdown',
                id: parentId,
                subindex: subindex,
                bitOffset: Number(bitOffset),
                bitLength: Number(bitLength),
                label: itemLabel,
                access: access,
                value: options[0] ? options[0].value : 0,
                options: options,
                isPd: isPd
            });
        } else if (sdtType === 'BooleanT' || sdtType.includes('Boolean')) {
            targetList.push({
                type: 'switch',
                id: parentId,
                subindex: subindex,
                bitOffset: Number(bitOffset),
                bitLength: 1,
                label: itemLabel,
                access: access,
                value: false,
                isPd: isPd
            });
        } else {
            let vr = findFirst(sdt, 'ValueRange');
            let minVal = vr ? Number(getAttr(vr, 'lowerValue') || 0) : 0;
            let maxVal = vr ? Number(getAttr(vr, 'upperValue') || 100) : 100;

            targetList.push({
                type: (access === 'ro' ? 'text' : 'slider'),
                id: parentId,
                subindex: subindex,
                bitOffset: Number(bitOffset),
                bitLength: Number(bitLength),
                label: itemLabel,
                access: access,
                value: minVal,
                min: minVal,
                max: maxVal,
                isPd: isPd
            });
        }
    });
}

// 4. PROCESS DATA ELEMZÉS
let pdOutList = findNodes(rawPayload, 'ProcessDataOut');
pdOutList.forEach(pd => {
    let pdDtRef = findFirst(pd, 'DatatypeRef');
    let pdDt = findFirst(pd, 'Datatype');
    if (!pdDt && pdDtRef) {
        let refId = getAttr(pdDtRef, 'datatypeId');
        if (refId && customTypes[refId]) pdDt = customTypes[refId];
    }
    let pdItems = findNodes(pdDt, 'RecordItem');
    if (pdItems.length > 0) {
        parseRecordItems(pdItems, 'ProcessDataOut', 'Process Data Kimenet', 'rw', pdOutElements, true);
    }
});

let pdInList = findNodes(rawPayload, 'ProcessDataIn');
pdInList.forEach(pd => {
    let pdDtRef = findFirst(pd, 'DatatypeRef');
    let pdDt = findFirst(pd, 'Datatype');
    if (!pdDt && pdDtRef) {
        let refId = getAttr(pdDtRef, 'datatypeId');
        if (refId && customTypes[refId]) pdDt = customTypes[refId];
    }
    let pdItems = findNodes(pdDt, 'RecordItem');
    if (pdItems.length > 0) {
        parseRecordItems(pdItems, 'ProcessDataIn', 'Process Data Bemenet', 'ro', pdInElements, true);
    }
});

// 5. ACIKLIKUS VÁLTOZÓK (ISDU)
let allVariables = findNodes(rawPayload, 'Variable');
allVariables.forEach(v => {
    if (!v) return;
    let varId = getAttr(v, 'id') || 'Var';
    let index = getAttr(v, 'index') || '0';
    let access = getAttr(v, 'accessRights') || 'rw';

    let nameNode = findFirst(v, 'Name');
    let rawName = getAttr(nameNode, 'textId') || varId;
    let groupLabel = resolveText(rawName, varId);

    let dtNode = findFirst(v, 'Datatype');
    let dtRef = findFirst(v, 'DatatypeRef');
    if (!dtNode && dtRef) {
        let refId = getAttr(dtRef, 'datatypeId');
        if (refId && customTypes[refId]) dtNode = customTypes[refId];
    }

    let recordItems = findNodes(dtNode, 'RecordItem');
    if (recordItems.length > 0) {
        parseRecordItems(recordItems, varId, groupLabel, access, paramElements, false);
    } else {
        let dtType = getAttr(dtNode, 'xsi:type') || getAttr(dtNode, 'datatype') || '';
        let vr = findFirst(dtNode, 'ValueRange');
        let minVal = vr ? Number(getAttr(vr, 'lowerValue') || 0) : 0;
        let maxVal = vr ? Number(getAttr(vr, 'upperValue') || 100) : 100;

        let singleValues = findNodes(dtNode, 'SingleValue');
        if (singleValues.length > 0) {
            let options = singleValues.map(sv => {
                let svVal = getAttr(sv, 'value');
                let svNameNode = findFirst(sv, 'Name');
                let svTextId = getAttr(svNameNode, 'textId');
                return {
                    name: resolveText(svTextId, svVal),
                    value: isNaN(Number(svVal)) ? svVal : Number(svVal)
                };
            });

            paramElements.push({
                type: 'dropdown',
                id: varId,
                index: index,
                label: groupLabel,
                access: access,
                value: options[0] ? options[0].value : 0,
                options: options,
                isPd: false
            });
        } else if (dtType.includes('Integer') || dtType.includes('Float') || dtType === 'UIntegerT') {
            paramElements.push({
                type: (access === 'ro' ? 'text' : 'slider'),
                id: varId,
                index: index,
                label: groupLabel,
                access: access,
                value: minVal,
                min: minVal,
                max: maxVal,
                isPd: false
            });
        } else if (dtType.includes('Boolean')) {
            paramElements.push({
                type: 'switch',
                id: varId,
                index: index,
                label: groupLabel,
                access: access,
                value: false,
                isPd: false
            });
        } else {
            paramElements.push({
                type: 'text',
                id: varId,
                index: index,
                label: groupLabel,
                access: access,
                value: '',
                isPd: false
            });
        }
    }
});

let allProcessData = pdInElements.concat(pdOutElements);

let schema = {
    vendorId: vendorId,
    deviceId: deviceId,
    vendorName: vendorName,
    productName: productName,
    image: msg.imageBase64,
    hasPdOut: pdOutElements.length > 0,
    hasPdIn: pdInElements.length > 0,
    processDataIn: pdInElements,
    processDataOut: pdOutElements,
    processData: allProcessData,       // <-- Ciklikus adatok a renderelőhöz
    parameters: paramElements
};

global.set('currentDeviceSchema', schema);
node.status({ fill: 'green', shape: 'dot', text: 'PD In: ' + pdInElements.length + ' | PD Out: ' + pdOutElements.length + ' | Param: ' + paramElements.length });

return { payload: schema };

let schema = global.get('currentDeviceSchema');
if (!schema) {
    node.warn('Nincs aktív IODD séma az adatok szűréséhez!');
    return null;
}

let raw = msg.payload;
let decoded = {
    device: schema.productName,
    timestamp: Date.now(),
    rawBytes: raw,
    status: 'Feldolgozva a sémához'
};

node.status({ fill: 'blue', shape: 'dot', text: 'Adat átengedve' });
return { payload: decoded };
